```cpp
#include <iostream>
#include <fstream>
#include <vector>
using namespace std;

int main() {
    ifstream plik("dane.txt");
    vector<int> T;
    int x;
    while (plik >> x) T.push_back(x);
    int n = T.size();

    int liczba = 0;
    vector<int> indeksy;
    long long suma = 0;

    for (int i = 0; i < n; i++) {
        suma += T[i];
        double sr = (double)suma / (i + 1);
        if (T[i] > sr) {
            liczba++;
            indeksy.push_back(i + 1);
        }
    }

    cout << "a) Liczba elementow powyzej sredniej biezacej: " << liczba << endl;
    cout << "b) Indeksy:";
    for (int idx : indeksy)
        cout << " " << idx;
    cout << endl;
    return 0;
}
```

**Wyjasnienie**: Utrzymujemy biezaca sume i obliczamy srednia na kazdym kroku. Porownujemy biezacy element z jego srednia biezaca.

